using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries reference c.Discriminator, so keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id value format changed.
            // EF Core 8 wrote id as "Product|123"; EF Core 9 writes just "123".
            // Use a custom value generator to keep producing the old format
            // so existing documents are still found by key lookup.
            entity.Property(p => p.Id)
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
        });

        // BREAKING CHANGE 3 — HasIndex is no longer silently ignored.
        // The Cosmos provider now throws for unsupported index definitions.
        // The original HasIndex(p => p.Sku) call has been removed.
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

